<?php
// Only use a disposable database; outgoing HTTP is mocked and no external messages are sent.
declare(strict_types=1);
if(PHP_SAPI!=='cli'||getenv('INTEGRATION_TEST_ALLOW_MUTATIONS')!=='1')exit("Use a disposable database with explicit mutation opt-in.\n");
require __DIR__.'/../server/config-loader.php';require __DIR__.'/../server/auth-policy.php';require __DIR__.'/../server/integrations-lib.php';require __DIR__.'/../server/records-service.php';require __DIR__.'/../server/connections.php';
$config=khushrang_load_config(getenv('KHUSHRANG_CONFIG'));$db=new PDO($config['dsn'],$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->exec("SET time_zone='+00:00'");$creds=json_decode(file_get_contents(getenv('API_TEST_CREDENTIALS_FILE')),true);$q=$db->prepare('SELECT * FROM users WHERE email=?');$q->execute([$creds['email']]);$user=$q->fetch();
function verify_connection(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}
$tag=bin2hex(random_bytes(8));$client='HOOKTEST-'.$tag;$hook=null;$jobs=[];$secret=bin2hex(random_bytes(16));$url='https://example.com/hooks/khushrang?key='.$tag;
try{
 $saved=connection_webhook_save($db,$config,$user,['name'=>'Connection test '.$tag,'url'=>$url,'active'=>true,'bearer_token'=>$secret]);$hook=$saved['id'];$q=$db->prepare('SELECT payload FROM records WHERE id=?');$q->execute(['integration-webhook-'.$hook]);$serialized=$q->fetchColumn();verify_connection(!str_contains($serialized,$secret)&&!str_contains($serialized,$url),'Secret or full URL stored in plaintext');$row=json_decode($serialized,true);$decoded=connection_decrypt($db,$config,$row['encrypted']);verify_connection($decoded['url']===$url&&$decoded['bearer_token']===$secret,'Webhook encryption round trip failed');
 business_save($db,'clients',['id'=>$client,'name'=>'Webhook fixture','email'=>'webhook-fixture@example.test','status'=>'Active']);$runtime=integration_runtime_config($db,$config);$job=integration_enqueue($db,['client_id'=>$client,'purpose'=>'transactional','destination_id'=>$hook,'idempotency_key'=>$tag.'-1'],$runtime);$jobs[]=$job['id'];$legacy=$db->prepare("SELECT COUNT(*) FROM integration_outbox WHERE id=? AND status IN ('pending','retry','processing')");$legacy->execute([$job['id']]);verify_connection((int)$legacy->fetchColumn()===0,'Obsolete workers can claim a new webhook job');$called=false;
 integration_work($db,$runtime,1,function($d,$body,$id)use(&$called,$secret){$called=true;verify_connection($d['bearer_token']===$secret,'Wrong outbound credential');verify_connection(json_decode($body,true)['event']==='client.sync','Wrong outbound event');return 204;},$job['id']);$q=$db->prepare('SELECT status FROM integration_outbox WHERE id=?');$q->execute([$job['id']]);verify_connection($called&&$q->fetchColumn()==='accepted','Named webhook was not delivered');
 $next=integration_enqueue($db,['client_id'=>$client,'purpose'=>'transactional','destination_id'=>$hook,'idempotency_key'=>$tag.'-2'],$runtime);$jobs[]=$next['id'];connection_webhook_save($db,$config,$user,['id'=>$hook,'name'=>'Changed test','url'=>$url,'active'=>true,'bearer_token'=>'replacement-test-only']);$called=false;integration_work($db,$runtime,1,function()use(&$called){$called=true;return 200;},$next['id']);$q=$db->prepare('SELECT status,last_error FROM integration_outbox WHERE id=?');$q->execute([$next['id']]);$failed=$q->fetch();verify_connection(!$called&&$failed['status']==='failed'&&str_contains($failed['last_error'],'settings changed'),'Queued data silently followed a changed webhook');
 connection_webhook_save($db,$config,$user,['id'=>$hook,'name'=>'Cleared test','url'=>$url,'active'=>false,'bearer_token'=>'','clear_secret'=>true]);$runtime=integration_runtime_config($db,$config);verify_connection(!$runtime['webhooks'][$hook]['active']&&$runtime['webhooks'][$hook]['bearer_token']==='','Credential removal or disable failed');
 foreach(['http://example.com/hook','https://localhost/hook','https://127.0.0.1/hook'] as $unsafe){try{connection_webhook_save($db,$config,$user,['name'=>'Unsafe','url'=>$unsafe,'active'=>true]);throw new LogicException('Unsafe URL accepted');}catch(IntegrationError $e){}}
 echo "PASS: encrypted webhook URL/credentials, named destinations, mocked delivery, changed-destination blocking, credential removal, disable, and unsafe URL rejection. No external messages sent.\n";
}finally{foreach($jobs as $id){$q=$db->prepare('DELETE FROM integration_outbox WHERE id=?');$q->execute([$id]);}if($hook){$q=$db->prepare('DELETE FROM records WHERE id=?');$q->execute(['integration-webhook-'.$hook]);}$q=$db->prepare('DELETE FROM records WHERE id=?');$q->execute([$client]);}
